+    __m512 c6l = accumulate ? _mm512_maskz_loadu_ps(low_mask, c + 6 * ldc) : _mm512_setzero_ps();
+    __m512 c7l = accumulate ? _mm512_maskz_loadu_ps(low_mask, c + 7 * ldc) : _mm512_setzero_ps();
